// Ready-made page content generated by `-g page <preset>`. Pages are still
// registered through the framework's normal route handling; copy is sample
// text the project replaces.
import { getFrameworkAdapter } from "../core/frameworks/index.mjs";

export const PAGE_PRESETS = ["home", "about", "consult"];

export function isPagePreset(name) {
  return PAGE_PRESETS.includes(name);
}

const copy = {
  home: {
    heading: "Build something people love",
    intro: "Explain what this product does and who it is for.",
    listLabel: "Highlights",
    items: ["Fast to start", "Structured with Feature-Sliced Design", "Ready to grow"],
  },
  about: {
    heading: "About us",
    intro: "Who you are, what you do, and why it matters.",
    listLabel: "Our values",
    items: ["Clarity", "Craft", "Care"],
  },
};

const CONSULT_FIELDS = [
  ["name", "Name", "text", "name"],
  ["email", "Email", "email", "email"],
  ["message", "How can we help?", "textarea", "off"],
];

export function reactPagePresetContent(name, config) {
  const component = `${name.charAt(0).toUpperCase()}${name.slice(1)}Page`;
  if (name === "consult") return reactConsultContent(component, config);
  const page = copy[name];
  return `export function ${component}() {
  return (
    <main>
      <section>
        <h1>${page.heading}</h1>
        <p>${page.intro}</p>
      </section>
      <section aria-label="${page.listLabel}">
        <h2>${page.listLabel}</h2>
        <ul>
${page.items.map((item) => `          <li>${item}</li>`).join("\n")}
        </ul>
      </section>
    </main>
  );
}
`;
}

function reactConsultContent(component, config) {
  const clientDirective = getFrameworkAdapter(config.framework).clientDirective;
  const fields = CONSULT_FIELDS.map(([field, label, type, autoComplete]) => {
    const control =
      type === "textarea"
        ? `<textarea id="consult-${field}" name="${field}" rows={5} required />`
        : `<input
            id="consult-${field}"
            name="${field}"
            type="${type}"
            autoComplete="${autoComplete}"
            required
          />`;
    return `        <div>
          <label htmlFor="consult-${field}">${label}</label>
          ${control}
        </div>`;
  }).join("\n");

  return `${clientDirective}import { type FormEvent, useState } from "react";

export type ConsultRequest = {
  name: string;
  email: string;
  message: string;
};

type ${component}Props = {
  onSubmit?: (request: ConsultRequest) => void | Promise<void>;
};

export function ${component}({ onSubmit }: ${component}Props) {
  const [sent, setSent] = useState(false);

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    await onSubmit?.({
      name: String(data.get("name") ?? ""),
      email: String(data.get("email") ?? ""),
      message: String(data.get("message") ?? ""),
    });
    setSent(true);
  }

  return (
    <main>
      <h1>Book a consultation</h1>
      <p>Tell us about your project and we will get back to you.</p>
      <form onSubmit={handleSubmit}>
${fields}
        <button type="submit">Send request</button>
      </form>
      {sent ? <p role="status">Thanks, we received your request.</p> : null}
    </main>
  );
}
`;
}

export function vuePagePresetContent(name) {
  if (name === "consult") return vueConsultContent();
  const page = copy[name];
  return `<template>
  <main>
    <section>
      <h1>${page.heading}</h1>
      <p>${page.intro}</p>
    </section>
    <section aria-label="${page.listLabel}">
      <h2>${page.listLabel}</h2>
      <ul>
${page.items.map((item) => `        <li>${item}</li>`).join("\n")}
      </ul>
    </section>
  </main>
</template>
`;
}

function vueConsultContent() {
  const fields = CONSULT_FIELDS.map(([field, label, type, autoComplete]) => {
    const control =
      type === "textarea"
        ? `<textarea
          id="consult-${field}"
          v-model="form.${field}"
          name="${field}"
          rows="5"
          required
        />`
        : `<input
          id="consult-${field}"
          v-model="form.${field}"
          name="${field}"
          type="${type}"
          autocomplete="${autoComplete}"
          required
        >`;
    return `      <div>
        <label for="consult-${field}">${label}</label>
        ${control}
      </div>`;
  }).join("\n");

  return `<script setup lang="ts">
import { reactive, ref } from "vue";

type ConsultRequest = {
  name: string;
  email: string;
  message: string;
};

const emit = defineEmits<{ submit: [request: ConsultRequest] }>();
const form = reactive<ConsultRequest>({ name: "", email: "", message: "" });
const sent = ref(false);

function handleSubmit() {
  emit("submit", { ...form });
  sent.value = true;
}
</script>

<template>
  <main>
    <h1>Book a consultation</h1>
    <p>Tell us about your project and we will get back to you.</p>
    <form @submit.prevent="handleSubmit">
${fields}
      <button type="submit">
        Send request
      </button>
    </form>
    <p
      v-if="sent"
      role="status"
    >
      Thanks, we received your request.
    </p>
  </main>
</template>
`;
}

export function sveltePagePresetContent(name) {
  if (name === "consult") return svelteConsultContent();
  const page = copy[name];
  return `<main>
  <section>
    <h1>${page.heading}</h1>
    <p>${page.intro}</p>
  </section>
  <section aria-label="${page.listLabel}">
    <h2>${page.listLabel}</h2>
    <ul>
${page.items.map((item) => `      <li>${item}</li>`).join("\n")}
    </ul>
  </section>
</main>
`;
}

function svelteConsultContent() {
  const fields = CONSULT_FIELDS.map(([field, label, type, autoComplete]) => {
    const control =
      type === "textarea"
        ? `<textarea id="consult-${field}" name="${field}" rows="5" required bind:value={form.${field}}></textarea>`
        : `<input id="consult-${field}" name="${field}" type="${type}" autocomplete="${autoComplete}" required bind:value={form.${field}} />`;
    return `    <div>
      <label for="consult-${field}">${label}</label>
      ${control}
    </div>`;
  }).join("\n");

  return `<script lang="ts">
  type ConsultRequest = { name: string; email: string; message: string };

  let { onsubmit }: { onsubmit?: (request: ConsultRequest) => void | Promise<void> } = $props();

  let form = $state<ConsultRequest>({ name: "", email: "", message: "" });
  let sent = $state(false);

  async function handleSubmit(event: SubmitEvent) {
    event.preventDefault();
    await onsubmit?.({ ...form });
    sent = true;
  }
</script>

<main>
  <h1>Book a consultation</h1>
  <p>Tell us about your project and we will get back to you.</p>
  <form onsubmit={handleSubmit}>
${fields}
    <button type="submit">Send request</button>
  </form>
  {#if sent}
    <p role="status">Thanks, we received your request.</p>
  {/if}
</main>
`;
}
